using FolderVerse;using Microsoft.Xna.Framework;using Microsoft.Xna.Framework.Graphics;using Microsoft.Xna.Framework.Input;using System.Reflection;
using var game=new TallySequenceUi(args[0]);game.Run();
sealed class TallySequenceUi(string output):Game1{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;WorldSetup w=null!;SpriteBatch batch=null!;int frame;
 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object v)=>typeof(Game1).GetField(n,F)!.SetValue(this,v);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!;
 void Check(bool ok,string m){if(!ok)throw new Exception(m);Console.WriteLine("PASS "+m);} protected override void LoadContent(){Window.Position=new(-3000,-3000);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));w=new(){EquipmentMode=RobotEquipmentMode.Materials};w.SetParticipantCounts(1,1);w.SetWorld(1);w.SetCast(2);w.SetPlacement(3);w.Relations.Reset();w.SelectPlayer(0);w.Relations.Leader=0;w.Robots.Initialize(w.Nodes.All.Length,w.ActiveCount);w.Robots.ConfigureFactories(w);w.Salvage.Reset();w.Salvage.EnableExpeditions(w);foreach(var n in w.Nodes.All)n.Owner=0;int h=w.Nodes.All.First(n=>n.Functional).Id;w.ConquerorLocations[0]=w.Nodes.All[h].Cell;w.ConquerorPoints[0]=w.Nodes.All[h].Center;
 foreach(var material in Enum.GetValues<RobotMaterial>()){var robot=w.Robots.Create(0,RobotParts.Complete,RobotRole.Captain) with{HeadMaterial=material,BodyMaterial=(RobotMaterial)(((int)material+1)%9),LegsMaterial=material};w.Robots.Nodes[h].Add(robot);var good=w.Robots.Create(1,RobotParts.Complete) with{HeadMaterial=material,BodyMaterial=material,LegsMaterial=material,IntegratedParts=(int)material%2==0?RobotParts.Head|RobotParts.Body:0};w.Salvage.Items.Add(new(1000+(int)material,h,good));}
 Set("_setup",w);batch=new(GraphicsDevice);var pixel=new Texture2D(GraphicsDevice,1,1);pixel.SetData(new[]{Color.White});Set("_spriteBatch",batch);Set("_pixel",pixel);Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");Set("_portraitRenderer",new PortraitRenderer(Content));var fonts=new Microsoft.Xna.Framework.Content.ContentManager(Services,Path.Combine(Environment.GetEnvironmentVariable("PROBE_FONT")!,"Content"));var font=fonts.Load<SpriteFont>("UiFont");Set("_font",font);Set("_ui",Activator.CreateInstance(typeof(Game1).GetField("_ui",F)!.FieldType,batch,pixel,font)!);Set("_conquestAudioUnavailable",true);Set("_screen",Enum.Parse(Get("_screen").GetType(),"WorldStatus")); foreach(var n in w.Nodes.All)n.Owner=n.Cell==0?0:n.Cell==1?1:-1;w.Relations.SetSuperior(1,0);var presentation=new ConquestPresentation(w);int index=Array.FindIndex(presentation.Cards,c=>c.Ruler==0&&!c.Reminder);Set("_conquestPresentation",presentation);Set("_conquestCard",index);Set("_conquestTally",new ConquestTally(w,presentation.Cards[index]));Set("_conquestStage",4);
 var tally=(ConquestTally)Get("_conquestTally");Check(tally.CellsStart<tally.MultiplyStart&&tally.MultiplyStart<tally.EntryStart&&tally.EntryStart<tally.ScoreStart&&tally.ScoreStart<tally.RankStart,"five stages are ordered");}
 protected override void Update(GameTime t){}
 protected override void Draw(GameTime t){
 var tally=(ConquestTally)Get("_conquestTally");var ages=new[]{0d,tally.CellsStart,tally.MultiplyStart,tally.EntryStart,tally.ScoreStart,tally.RankStart};Set("_conquestAge",ages[frame]);
 using var image=new RenderTarget2D(GraphicsDevice,1920,1080);GraphicsDevice.SetRenderTarget(image);GraphicsDevice.Clear(Color.White);batch.Begin();Call("DrawConquestTally");batch.End();GraphicsDevice.SetRenderTarget(null);var pixels=new Color[1920*1080];image.GetData(pixels);
 for(int row=0;row<5;row++){int dark=0;for(int y=370+row*70+5;y<370+row*70+68;y++)for(int x=1280;x<1800;x++){var c=pixels[y*1920+x];if(c.R<150&&c.G<150&&c.B<150)dark++;}Check((dark>0)==(row<frame),"only revealed rows visible stage="+frame+" row="+row);}
 using(var file=File.Create(Path.Combine(output,$"tally-stage-{frame}.png")))image.SaveAsPng(file,1920,1080);if(++frame==ages.Length){Console.WriteLine("PASS all five stages rendered without preprinted labels");Exit();}
 }
}